@php $inc = DB::table('salary_history as h')->join('employees as e','e.id','=','h.employee_id')->select('e.name','h.employee_id', DB::raw('count(*) c'), DB::raw('avg(h.change_amount) aa'), DB::raw('avg(h.change_pct) ap'), DB::raw('max(h.effective_date) last'))->where('h.change_amount','>',0)->groupBy('e.name','h.employee_id')->orderBy('e.name')->get(); $all = DB::table('salary_history')->where('change_amount','>',0); @endphp
