@php $ms = DB::table('payroll_entries')->select('month', DB::raw('count(*) n'), DB::raw('sum(amount) tot'), DB::raw("sum(case when status='paid' then amount else 0 end) paid"), DB::raw("sum(case when status='paid' then 1 else 0 end) pn"))->groupBy('month')->orderByDesc('month')->get(); @endphp
<div class="card" style="margin-top:14px"><b>Monthly summary (প্রতি মাসের সামারি)</b> <span style="font-size:12px;color:#6B7280">Builds itself every month. A month turns Paid when every row is paid.</span>
<table><thead><tr><th>Month</th><th>Employees</th><th style="text-align:right">Total</th><th style="text-align:right">Paid</th><th style="text-align:right">Due (বকেয়া)</th><th>Status</th><th></th></tr></thead><tbody>@forelse($ms as $m)@php $due = $m->tot - $m->paid; $lab = \Carbon\Carbon::createFromFormat('Y-m-d', $m->month.'-01')->format('F Y'); @endphp<tr><td>{{ $lab }}</td><td>{{ $m->pn }}/{{ $m->n }} paid</td><td style="text-align:right">৳{{ number_format($m->tot) }}</td><td style="text-align:right">৳{{ number_format($m->paid) }}</td><td style="text-align:right"><b style="color:{{ $due > 0 ? '#B91C1C' : '#166534' }}">৳{{ number_format($due) }}</b></td><td>{{ $m->pn >= $m->n ? 'Paid' : ($m->pn > 0 ? 'Partly paid' : 'Unpaid') }}</td><td><a href="/admin/payroll-sheet/{{ $m->month }}">Salary sheet</a></td></tr>@empty<tr><td colspan="7" style="color:#6B7280">No payroll yet. The first month appears automatically.</td></tr>@endforelse</tbody></table></div>
